import{_ as e,o as i,c as s,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const _=JSON.parse('{"title":"Ceph Performance Meeting 2019-01-10","description":"","frontmatter":{"title":"Ceph Performance Meeting 2019-01-10","date":"2019-01-10T00:00:00.000Z","updated":"2019-01-16T00:00:00.000Z","tags":["Ceph","分布式存储","Crimson项目","性能优化","Pull Requests"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/Ceph_Performance_Meeting_2019-01-10.md","filePath":"posts/2019/Ceph_Performance_Meeting_2019-01-10.md","lastUpdated":1780460162000}'),r={name:"posts/2019/Ceph_Performance_Meeting_2019-01-10.md"};function o(n,l,p,a,u,g){return i(),s("div",null,[...l[0]||(l[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2019年1月10日</p><p><strong>参会人员</strong>： (此处应填写参会人员名单)</p><p><strong>会议主题</strong>： Ceph分布式存储项目进展及Crimson项目讨论</p><p><strong>会议内容</strong>：</p><p><strong>一、Ceph项目进展</strong></p><ol><li><p><strong>Pull Requests审查</strong>：</p><ul><li>会议讨论了多个Pull Requests，包括Stack Streams、FS分配、优先级缓存大小调整、EC Cash等。</li><li>部分Pull Requests已合并，如优先级缓存大小调整。</li><li>需要进一步审查的Pull Requests包括EC Cash、共享LRU等。</li></ul></li><li><p><strong>Crimson项目讨论</strong>：</p><ul><li>Crimson项目旨在优化Ceph的性能，特别是对象存储层。</li><li>项目初期目标是验证假设，包括验证Crimson对性能的帮助。</li><li>项目设计采用简化设计，以降低维护成本和复杂性。</li><li>讨论了Crimson的OSD概念，包括如何实现多线程OSD。</li><li>讨论了使用mstar线程模型的可能性，以及如何与SPDK集成。</li></ul></li></ol><p><strong>二、行动计划</strong></p><ol><li><p><strong>Ceph项目</strong>：</p><ul><li>继续审查和合并Pull Requests。</li><li>对EC Cash、共享LRU等Pull Requests进行进一步审查。</li></ul></li><li><p><strong>Crimson项目</strong>：</p><ul><li>完成Crimson的简化设计。</li><li>与SPDK团队合作，确定最佳线程模型。</li><li>开展Crimson的测试工作。</li></ul></li></ol><p><strong>三、后续会议</strong></p><ul><li>下次会议将于近期举行，届时将讨论Crimson项目的进展和后续计划。</li></ul><p><strong>四、其他事项</strong></p><ul><li>会议中讨论了RocksDB的使用，以及如何将其与Ceph集成。</li><li>讨论了Crimson项目对性能的影响，以及如何评估其效果。</li></ul><p><strong>五、关键词</strong></p><ul><li>Pull Requests</li><li>Stack Streams</li><li>FS分配</li><li>优先级缓存大小调整</li><li>EC Cash</li><li>共享LRU</li><li>Crimson项目</li><li>OSD</li><li>mstar线程模型</li><li>SPDK</li></ul>',15)])])}const m=e(r,[["render",o]]);export{_ as __pageData,m as default};
